                    if (diag != 0u) { return diag; }
                }
                if (x < GRID_WIDTH - 1u) {
                    let diag = check_displace(x + 1u, y + 1u, my_density);
                    if (diag != 0u) { return diag; }
                }
            } else {
                // Right first
                if (x < GRID_WIDTH - 1u) {
                    let diag = check_displace(x + 1u, y + 1u, my_density);
                    if (diag != 0u) { return diag; }
                }
                if (x > 0u) {
                    let diag = check_displace(x - 1u, y + 1u, my_density);
                    if (diag != 0u) { return diag; }
                }
            }
        }
    }

    // === HORIZONTAL SPREAD (fluids only) ===
    if (is_fluid(phase)) {
        if (parity == 0u) {
            if (x > 0u) {
                let left = check_displace(x - 1u, y, my_density);
                if (left != 0u) { return left; }
            }
            if (x < GRID_WIDTH - 1u) {
