// Optimized swap resolution with cached neighbor reads
fn resolve_swap(x: u32, y: u32, voxel: u32, phase: u32, my_density: u32) -> u32 {
    let parity = (x + y) & 1u;

    // Cache boundary checks
    let has_below = y < GRID_HEIGHT - 1u;
    let has_above = y > 0u;
    let has_left = x > 0u;
    let has_right = x < GRID_WIDTH - 1u;

    // Check straight down first (most common case)
    if (has_below) {
        let below = grid_in[get_idx(x, y + 1u)];
        let below_mat = get_material(below);
        let below_density = density_of(below_mat);

        if (my_density > below_density && (is_movable(get_phase(below)) || below_mat == MAT_AIR)) {
            return below;
        }

        // If blocked below, try diagonals
        if (my_density <= below_density) {
            // Read both diagonal neighbors at once to improve cache locality
            let dl_valid = has_left && has_below;
            let dr_valid = has_right && has_below;

            if (dl_valid || dr_valid) {
                let dl = select(0u, grid_in[get_idx(x - 1u, y + 1u)], dl_valid);
                let dr = select(0u, grid_in[get_idx(x + 1u, y + 1u)], dr_valid);

                let dl_density = select(255u, density_of(get_material(dl)), dl_valid);
                let dr_density = select(255u, density_of(get_material(dr)), dr_valid);

