                let dr_can_swap = dr_valid && my_density > dr_density && 
                    (is_movable(get_phase(dr)) || get_material(dr) == MAT_AIR);

                // Parity-based priority
                if (parity == 0u) {
                    if (dl_can_swap) { return dl; }
                    if (dr_can_swap) { return dr; }
                } else {
                    if (dr_can_swap) { return dr; }
                    if (dl_can_swap) { return dl; }
                }
            }
        }
    }

    // Horizontal spread for fluids
    if (is_fluid(phase)) {
        let l_valid = has_left;
        let r_valid = has_right;

        if (l_valid || r_valid) {
            let l = select(0u, grid_in[get_idx(x - 1u, y)], l_valid);
            let r = select(0u, grid_in[get_idx(x + 1u, y)], r_valid);

            let l_density = select(255u, density_of(get_material(l)), l_valid);
            let r_density = select(255u, density_of(get_material(r)), r_valid);

            let l_can_swap = l_valid && my_density > l_density && 
                (is_movable(get_phase(l)) || get_material(l) == MAT_AIR);
            let r_can_swap = r_valid && my_density > r_density && 
                (is_movable(get_phase(r)) || get_material(r) == MAT_AIR);

            if (parity == 0u) {
                if (l_can_swap) { return l; }
                if (r_can_swap) { return r; }
            } else {
                if (r_can_swap) { return r; }
                if (l_can_swap) { return l; }
            }
        }
