                let diag = grid_in[get_idx(x - 1u, y + 1u)];
                let diag_mat = get_material(diag);
                let diag_density = density_of(diag_mat);
                if (my_density > diag_density && (is_movable(get_phase(diag)) || diag_mat == MAT_AIR)) {
                    return diag;
                }
            }
        }
    }

    // Horizontal spread for fluids
    if (is_fluid(phase)) {
        let try_left_first = parity == 0u;

        if (try_left_first && x > 0u) {
            let left = grid_in[get_idx(x - 1u, y)];
            let left_mat = get_material(left);
            let left_density = density_of(left_mat);
            if (my_density > left_density && (is_movable(get_phase(left)) || left_mat == MAT_AIR)) {
                return left;
            }
        }

        if (x < GRID_WIDTH - 1u) {
            let right = grid_in[get_idx(x + 1u, y)];
            let right_mat = get_material(right);
            let right_density = density_of(right_mat);
            if (my_density > right_density && (is_movable(get_phase(right)) || right_mat == MAT_AIR)) {
                return right;
            }
        }

        if (!try_left_first && x > 0u) {
            let left = grid_in[get_idx(x - 1u, y)];
            let left_mat = get_material(left);
            let left_density = density_of(left_mat);
            if (my_density > left_density && (is_movable(get_phase(left)) || left_mat == MAT_AIR)) {
                return left;
            }
        }
    }

    // Buoyancy check
    if (y > 0u) {
        let above = grid_in[get_idx(x, y - 1u)];
        let above_mat = get_material(above);
        let above_density = density_of(above_mat);
        if (above_density > my_density && (is_movable(get_phase(above)) || above_mat == MAT_AIR)) {
            return above;
        }
    }

    return voxel;
}

