evolvable_code._full_shader:
// Optimized density caching with streamlined diagonal checks

@group(0) @binding(0) var<storage, read> grid_in: array<u32>;
@group(0) @binding(1) var<storage, read_write> grid_out: array<u32>;
@group(0) @binding(2) var<storage, read> cold_table: array<u32>;

const COLD_STRIDE: u32 = 8u;
const COLD_DENSITY: u32 = 0u;

fn get_idx(x: u32, y: u32) -> u32 { return y * GRID_WIDTH + x; }
fn get_material(p: u32) -> u32 { return (p >> MATERIAL_SHIFT) & MATERIAL_MASK; }
fn get_phase(p: u32) -> u32 { return (p >> PHASE_SHIFT) & PHASE_MASK; }

fn density_of(mat: u32) -> u32 {
    return cold_table[mat * COLD_STRIDE + COLD_DENSITY];
}

fn is_movable(ph: u32) -> bool {
    return ph == PHASE_POWDER || ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_GAS;
}

fn is_fluid(ph: u32) -> bool {
    return ph == PHASE_LIQUID || ph == PHASE_VISCOUS || ph == PHASE_GAS;
}

// Optimized swap resolution with cached density values
fn resolve_swap(x: u32, y: u32, voxel: u32, my_density: u32, phase: u32) -> u32 {
    let parity = (x + y) & 1u;

    // === FALLING (check below) ===
    if (y < GRID_HEIGHT - 1u) {
        let below_idx = get_idx(x, y + 1u);
        let below = grid_in[below_idx];
        let below_mat = get_material(below);
        let below_density = density_of(below_mat);

        if (my_density > below_density && (is_movable(get_phase(below)) || below_mat == MAT_AIR)) {
            return below;
        }

        // === DIAGONAL FALL (if blocked straight down) ===
        if (my_density <= below_density) {
            // Try diagonals based on parity
            if (parity == 0u) {
                // Left first
                if (x > 0u) {
                    let diag = grid_in[get_idx(x - 1u, y + 1u)];
                    let diag_mat = get_material(diag);
                    if (my_density > density_of(diag_mat) && (is_movable(get_phase(diag)) || diag_mat == MAT_AIR)) {
                        return diag;
                    }
                }
                // Then right
                if (x < GRID_WIDTH - 1u) {
                    let diag = grid_in[get_idx(x + 1u, y + 1u)];
                    let diag_mat = get_material(diag);
                    if (my_density > density_of(diag_mat) && (is_movable(get_phase(diag)) || diag_mat == MAT_AIR)) {
                        return diag;
                    }
                }
            } else {
                // Right first
                if (x < GRID_WIDTH - 1u) {
                    let diag = grid_in[get_idx(x + 1u, y + 1u)];
                    let diag_mat = get_material(diag);
                    if (my_density > density_of(diag_mat) && (is_movable(get_phase(diag)) || diag_mat == MAT_AIR)) {
                        return diag;
                    }
                }
                // Then left
                if (x > 0u) {
                    let diag = grid_in[get_idx(x - 1u, y + 1u)];
                    let diag_mat = get_material(diag);
                    if (my_density > density_of(diag_mat) && (is_movable(get_phase(diag)) || diag_mat == MAT_AIR)) {
                        return diag;
                    }
                }
            }
        }
    }

    // === HORIZONTAL SPREAD (fluids only) ===
    if (is_fluid(phase)) {
        if (parity == 0u) {
            // Left first
            if (x > 0u) {
                let horiz = grid_in[get_idx(x - 1u, y)];
                let horiz_mat = get_material(horiz);
                if (my_density > density_of(horiz_mat) && (is_movable(get_phase(horiz)) || horiz_mat == MAT_AIR)) {
                    return horiz;
                }
            }
            // Then right
            if (x < GRID_WIDTH - 1u) {
                let horiz = grid_in[get_idx(x + 1u, y)];
                let horiz_mat = get_material(horiz);
                if (my_density > density_of(horiz_mat) && (is_movable(get_phase(horiz)) || horiz_mat == MAT_AIR)) {
                    return horiz;
                }
            }
        } else {
            // Right first
            if (x < GRID_WIDTH - 1u) {
                let horiz = grid_in[get_idx(x + 1u, y)];
                let horiz_mat = get_material(horiz);
                if (my_density > density_of(horiz_mat) && (is_movable(get_phase(horiz)) || horiz_mat == MAT_AIR)) {
                    return horiz;
                }
            }
            // Then left
            if (x > 0u) {
                let horiz = grid_in[get_idx(x - 1u, y)];
                let horiz_mat = get_material(horiz);
                if (my_density > density_of(horiz_mat) && (is_movable(get_phase(horiz)) || horiz_mat == MAT_AIR)) {
                    return horiz;
                }
            }
        }
    }

    // === BUOYANCY (check above) ===
    if (y > 0u) {
        let above = grid_in[get_idx(x, y - 1u)];
        let above_mat = get_material(above);
        let above_density = density_of(above_mat);

        if (above_density > my_density && (is_movable(get_phase(above)) || above_mat == MAT_AIR)) {
            return above;
        }
    }

    return voxel;
}

@compute @workgroup_size(16, 16)
fn tick(@builtin(global_invocation_id) gid: vec3<u32>) {
    let x = gid.x;
    let y = gid.y;
    if (x >= GRID_WIDTH || y >= GRID_HEIGHT) { return; }

    let idx = get_idx(x, y);
    let voxel = grid_in[idx];
    let mat = get_material(voxel);
    let phase = get_phase(voxel);

    if (!is_movable(phase) && mat != MAT_AIR) {
        grid_out[idx] = voxel;
        return;
    }

    let my_density = density_of(mat);
    grid_out[idx] = resolve_swap(x, y, voxel, my_density, phase);
}
